#include "conv_standard_1d_dilated_strided_custom_tiling.h"
#include "register/op_def_registry.h"

namespace {
inline int64_t GetDimSafe(const gert::Shape* s, size_t idx) {
    if (s->GetDimNum() <= idx) return 0;
    return s->GetDim(idx);
}
}

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard1dDilatedStridedCustomTilingData tiling;

    // Input shapes
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);
    const gert::Shape* b_shape = context->GetInputShape(2);

    uint32_t N    = static_cast<uint32_t>(GetDimSafe(x_shape, 0));
    uint32_t Cin  = static_cast<uint32_t>(GetDimSafe(x_shape, 1));
    uint32_t Lin  = static_cast<uint32_t>(GetDimSafe(x_shape, 2));
    uint32_t Cout = static_cast<uint32_t>(GetDimSafe(w_shape, 0));
    uint32_t K    = static_cast<uint32_t>(GetDimSafe(w_shape, 2));

    // Attributes
    int64_t stride_attr = 1;
    int64_t dilation_attr = 1;
    (void)context->GetAttr("stride", stride_attr);
    (void)context->GetAttr("dilation", dilation_attr);
    uint32_t stride = static_cast<uint32_t>(stride_attr);
    uint32_t dilation = static_cast<uint32_t>(dilation_attr);

    // Output length (valid conv)
    uint32_t lout = 0;
    if (Lin >= (dilation * (K - 1) + 1) && stride > 0) {
        lout = static_cast<uint32_t>((static_cast<int64_t>(Lin) - static_cast<int64_t>(dilation) * (static_cast<int64_t>(K) - 1) - 1) / static_cast<int64_t>(stride) + 1);
    }

    // Set block and tiling
    context->SetBlockDim(BLOCK_DIM);
    tiling.set_n(N);
    tiling.set_cin(Cin);
    tiling.set_lin(Lin);
    tiling.set_cout(Cout);
    tiling.set_k(K);
    tiling.set_stride(stride);
    tiling.set_dilation(dilation);
    tiling.set_lout(lout);
    tiling.set_tileNum(TILE_NUM);

    // hasBias
    uint32_t hasBias = 0;
    if (b_shape != nullptr && b_shape->GetDimNum() >= 1 && GetDimSafe(b_shape, 0) == Cout) {
        hasBias = 1;
    }
    tiling.set_hasBias(hasBias);

    // Infer output shape
    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(3);
    y_shape->SetDim(0, N);
    y_shape->SetDim(1, Cout);
    y_shape->SetDim(2, lout);

    // Save tiling
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // Workspace
    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0;

    return ge::GRAPH_SUCCESS;
}
} // namespace optiling

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    int64_t N    = x_shape->GetDim(0);
    int64_t Cin  = x_shape->GetDim(1);
    int64_t Lin  = x_shape->GetDim(2);
    int64_t Cout = w_shape->GetDim(0);
    int64_t K    = w_shape->GetDim(2);

    int64_t stride = 1;
    int64_t dilation = 1;
    (void)context->GetAttr("stride", stride);
    (void)context->GetAttr("dilation", dilation);

    int64_t lout = 0;
    if (Lin >= (dilation * (K - 1) + 1) && stride > 0) {
        lout = (Lin - dilation * (K - 1) - 1) / stride + 1;
    }

    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(3);
    y_shape->SetDim(0, N);
    y_shape->SetDim(1, Cout);
    y_shape->SetDim(2, lout);
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
