python_bind_src="""
#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

static inline at::Tensor empty_bias_like(const at::Tensor& ref) {
    return at::empty({0}, ref.options());
}

at::Tensor conv_standard_1d_dilated_strided_custom_impl_npu(
    const at::Tensor& x,
    const at::Tensor& w,
    c10::optional<at::Tensor> b_opt,
    int64_t stride,
    int64_t dilation) {

    at::Tensor y = at::empty({x.size(0), w.size(0),
                              (x.size(2) >= (int64_t)(dilation * (w.size(2) - 1) + 1))
                                ? ((x.size(2) - dilation * (w.size(2) - 1) - 1) / stride + 1)
                                : 0}, x.options());

    at::Tensor b = b_opt.has_value() && b_opt.value().defined() ? b_opt.value() : empty_bias_like(x);

    EXEC_NPU_CMD(aclnnConvStandard1dDilatedStridedCustom, x, w, b, stride, dilation, y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("conv_standard_1d_dilated_strided_custom", &conv_standard_1d_dilated_strided_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_standard_1d_dilated_strided_custom", &conv_standard_1d_dilated_strided_custom_impl_npu,
          "1D conv (stride/dilation)");
}
